string name = "Valentina";
int vokale = 0;

foreach (char c in name)
{
    if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u')
    {
        vokale++;
    }
}

Console.WriteLine($"{name} hat {vokale} Vokale.");
// Ausgabe: Valentina hat 4 Vokale.

string passwort = "Sommer2026";
int ziffern = 0;
int grosse = 0;

for (int i = 0; i < passwort.Length; i++)
{
    if (char.IsDigit(passwort[i])) ziffern++;
    if (char.IsUpper(passwort[i])) grosse++;
}

Console.WriteLine($"Ziffern: {ziffern}, Großbuchstaben: {grosse}");
// Ausgabe: Ziffern: 4, Großbuchstaben: 1

string wort = "Lager";
string umgedreht = "";

for (int i = wort.Length - 1; i >= 0; i--)
{
    umgedreht += wort[i];   // Zeichen hinten anhängen
}

Console.WriteLine(umgedreht);
// Ausgabe: regaL

